from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = set()
    queue = deque([(0, 0, 0, False)])  # (x, y, steps, broken)

    while queue:
        x, y, steps, broken = queue.popleft()
        if (x, y) == (m-1, n-1):
            return steps
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n:
                if grid[nx][ny] == '1' and not broken:
                    queue.append((nx, ny, steps+1, True))
                elif grid[nx][ny] == '0' and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, steps+1, broken))
    return -1
