def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    for instruction in program:
        if instruction.isdigit():
            stack.append(int(instruction))
        elif instruction == 'POP':
            if len(stack) == 0:
                raise IndexError("POP from empty stack")
            stack.pop()
        elif instruction == 'DUP':
            if len(stack) == 0:
                raise IndexError("DUP from empty stack")
            stack.append(stack[-1])
        elif instruction == 'SWAP':
            if len(stack) < 2:
                raise IndexError("SWAP from stack with less than 2 elements")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif instruction == 'ADD':
            if len(stack) < 2:
                raise IndexError("ADD from stack with less than 2 elements")
            stack.append(stack.pop() + stack.pop())
        elif instruction == 'SUB':
            if len(stack) < 2:
                raise IndexError("SUB from stack with less than 2 elements")
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif instruction == 'MUL':
            if len(stack) < 2:
                raise IndexError("MUL from stack with less than 2 elements")
            stack.append(stack.pop() * stack.pop())
        elif instruction == 'DIV':
            if len(stack) < 2:
                raise IndexError("DIV from stack with less than 2 elements")
            a = stack.pop()
            b = stack.pop()
            if a == 0:
                raise ZeroDivisionError("division by zero")
            stack.append(b // a)
        else:
            raise ValueError(f"Unknown instruction: {instruction}")
    return stack
