def run_stack_program(program: list[str]) -> list[int] | None:
    stack = []
    for command in program:
        if command.isdigit():
            stack.append(int(command))
        elif command == 'POP':
            if not stack:
                return None
            stack.pop()
        elif command == 'DUP':
            if not stack:
                return None
            stack.append(stack[-1])
        elif command == '+':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() + stack.pop())
        elif command == '-':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            stack.append(b - a)
        elif command == '*':
            if len(stack) < 2:
                return None
            stack.append(stack.pop() * stack.pop())
        elif command == '/':
            if len(stack) < 2:
                return None
            a = stack.pop()
            b = stack.pop()
            if a == 0:
                return None
            stack.append(b // a)
        else:
            return None
    return stack
