def lex_topological_order(n: int, pairs: list[tuple[int, int]]) -> list[int]:
    # Create adjacency list
    adj_list = {i: [] for i in range(1, n+1)}
    for pair in pairs:
        adj_list[pair[0]].append(pair[1])

    # Initialize visited and recursion stack
    visited = [False] * (n+1)
    stack = []

    # DFS traversal
    def dfs(node):
        visited[node] = True
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                dfs(neighbor)
        stack.append(node)

    # Call DFS for all unvisited nodes
    for node in range(1, n+1):
        if not visited[node]:
            dfs(node)

    # Reverse stack to get topological order
    topological_order = stack[::-1]

    return topological_order
