import collections
import heapq

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = collections.defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    shortest_distances = [float('inf')] * n
    shortest_distances[source] = 0
    queue = [(0, source)]
    while queue:
        dist, node = heapq.heappop(queue)
        if dist != shortest_distances[node]:
            continue
        for neighbor in graph[node]:
            if shortest_distances[node] + 1 < shortest_distances[neighbor]:
                shortest_distances[neighbor] = shortest_distances[node] + 1
                heapq.heappush(queue, (shortest_distances[neighbor], neighbor))

    count = 0
    for dist in shortest_distances:
        if dist == shortest_distances[target]:
            count += 1

    return count
