        if text[i] in ['.', '!', '?'] and text[i-1] != ' ':
            text = text[:i] + ' ' + text[i:].replace(text[i] + ' ', text[i] + ' ', 1)

    return text

def tidy_punctuation(text: str) -> str:
    # Replace multiple spaces with a single space
    text = ' '.join(text.split())

    # Replace punctuation that comes after a space with a single space
    for punctuation in ['.,!?:;-', '.,!?:;-']:
        for char in punctuation:
            text = text.replace(' ' + char, char)

    # Capitalize the first letter and the letter after ., !, ? with a space
    for punctuation in ['.', '!', '?']:
        text = text.replace(punctuation + ' ', lambda match: match.group().upper())

    return text

