def count_set_bits_range(lo: int, hi: int) -> int:
    if lo > hi or hi > 10**12:
        return 0
    total_count = 0
    for num in range(lo, hi+1):
        binary_num = bin(num)[2:]  # Remove the '0b' prefix
        count = binary_num.count('1')
        total_count += count
    return total_count

