from collections import defaultdict

def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    low = [0] * n
    disc = [-1] * n
    bridges = []

    def dfs(node, parent=-1):
        static_node = node
        low[node] = disc[node] = len(disc)
        for neighbor in graph[node]:
            if disc[neighbor] == -1:
                dfs(neighbor, parent=node)
                low[static_node] = min(low[static_node], low[neighbor])
                if low[neighbor] > disc[static_node]:
                    bridges.append((static_node, neighbor))
            elif neighbor != parent:
                low[static_node] = min(low[static_node], disc[neighbor])

    for node in range(n):
        if disc[node] == -1:
            dfs(node)

    return bridges
