    disc = [-1] * n
    bridges = []

    def dfs(u, parent):
        nonlocal time
        time += 1
        low[u] = disc[u] = time
        for v in graph[u]:
            if disc[v] == -1:
                dfs(v, parent)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v))
            elif v != parent:
                low[u] = min(low[u], disc[v])

    time = 0
    dfs(0, -1)

    return sorted(bridges)

