def expand_template(template: str, values: dict[str, str]) -> str:
    result = ""
    placeholder = ""
    in_placeholder = False
    for char in template:
        if char == "{":
            in_placeholder = True
            placeholder = ""
        elif char == "}":
            in_placeholder = False
            result += values.get(placeholder, "{" + placeholder + "}")
        elif in_placeholder:
            placeholder += char
        else:
            result += char
