def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    blocked_set = set(blocked)
    def is_attacked(i, j):
        return any(
            (i == i1 and j == j1) or
            (i == i1 or j == j1) or
            (i - j == i1 - j1) or
            (i + j == i1 + j1)
            for i1, j1 in blocked_set
        )
    def place_queen(i):
        if i == n:
            return 1
        return sum(
            place_queen(i + 1)
            for j in range(n)
            if not is_attacked(i, j)
        )
    return place_queen(0)
```

