    # Sort jobs in decreasing order of profit
    jobs.sort(key=lambda x: x[2], reverse=True)

    # Initialize result list with zeros
    result = ['0'] * jobs[0][1]

    for job in jobs:
        # Try to find a slot for the job
        for i in range(job[1]-1, -1, -1):
            if result[i] == '0':
                result[i] = job[0]
