def cheapest_route(edges: list[tuple[str, str, int]], start: str, goal: str) -> tuple[int, list[str]] | None:
    graph = {}
    for u, v, cost in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append((v, cost))
        graph[v].append((u, cost))

    queue = [(0, start, [])]
    seen = set()
    while queue:
        (cost, node, path) = heapq.heappop(queue)
        if node not in seen:
            seen.add(node)
            path = path + [node]
            if node == goal:
                return cost, path
            for (next_node, next_cost) in graph.get(node, []):
                if next_node not in seen:
                    heapq.heappush(queue, (cost + next_cost, next_node, path))
    return None
