from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start, end = (0, 0), (rows-1, cols-1)
    visited = {(0, 0): (0, False)}
    queue = deque([(0, 0, 0, False)])

    while queue:
        r, c, d, broke_wall = queue.popleft()
        if (r, c) == end:
            return d
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '1' and not broke_wall:
                    queue.append((nr, nc, d+1, True))
                    visited[(nr, nc)] = (d+1, True)
                elif grid[nr][nc] == '0' and (nr, nc) not in visited:
                    queue.append((nr, nc, d+1, broke_wall))
                    visited[(nr, nc)] = (d+1, broke_wall)
    return -1
