from collections import deque

def min_slides(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]  # right, left, down, up

    # Find the start and end positions
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
            if grid[r][c] == 'E':
                end = (r, c)

    # Initialize the queue with the start position and the number of slides
    queue = deque([(start, 0)])
    visited = {start}

    while queue:
        (r, c), slides = queue.popleft()

        # If we reach the end, return the number of slides
        if (r, c) == end:
            return slides

        # Explore all possible directions
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] != '#' and (nr, nc) not in visited:
                queue.append(((nr, nc), slides + 1))
                visited.add((nr, nc))

    # If we reach here, it means we can't reach the end
    return -1
