def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end or min_len < 0:
        return []

    busy.sort()
    free = []
    last_end = day_start

    for start, end in busy:
        if start > day_end or end < day_start:
            continue
        if start > last_end:
            free.append((last_end, min(start, day_end)))
        last_end = max(last_end, end)

    if last_end < day_end:
        free.append((last_end, day_end))

    return [(start, end) for start, end in free if end - start >= min_len]
