def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ''

    # Calculate the width of each column
    widths = [max(len(row[col]) for row in rows) for col in range(len(rows[0]))]

    # Create a new table
    table = []
    for row in rows:
        new_row = []
        for i, cell in enumerate(row):
            align = aligns[i % len(aligns)]
            if align == '<':
                new_row.append(cell.ljust(widths[i]))
            elif align == '>':
                new_row.append(cell.rjust(widths[i]))
            elif align == '^':
                new_row.append(cell.center(widths[i]))
        table.append(' | '.join(new_row))

    return '\n'.join(table)

