    if not grid:
        return []

    rows, cols = len(grid), len(grid[0])
    stable = False
    while not stable:
        stable = True
        new_grid = [[0]*cols for _ in range(rows)]
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] >= 4:
                    stable = False
                    new_grid[i][j] += 1
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = i + dx, j + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            new_grid[nx][ny] += 1
                else:
                    new_grid[i][j] = grid[i][j]
        grid = new_grid
    return grid

