def subsets_with_sum(nums: list[int], k: int) -> list[list[int]]:
    def dfs(nums, target, path, res):
        if target < 0:
            return  # backtracking
        if target == 0:
            res.append(path)
            return 
        for i in range(len(nums)):
            # i != start to avoid duplicates
            # e.g., [1, 2, 3] and [3, 2, 1] are the same subset
            # but [1, 2, 2] and [2, 1, 2] are not
            if i > 0 and nums[i] == nums[i-1]:
                continue
            # choose
            dfs(nums[i+1:], target-nums[i], path+[nums[i]], res)

    res = []
    nums.sort() # sort the numbers
    dfs(nums, k, [], res)
    return res

