def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = {}
    waiting = []

    for event in events:
        action, item, quantity = event

        if action == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity

        elif action == 'order':
            if item in stock and stock[item] >= quantity:
                stock[item] -= quantity
                if stock[item] == 0:
                    del stock[item]

            elif item in stock and stock[item] < quantity:
                waiting.append((item, quantity - stock[item]))
                stock[item] = 0
                del stock[item]

            else:
                waiting.append(event)

    return stock, waiting
