    rows, cols = len(grid), len(grid[0])
    start, end = None, None
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c, 0)  # (row, col, wall breaks)
            elif grid[r][c] == 'E':
                end = (r, c)
    if start is None or end is None:
        return -1

    queue = deque([start])
    visited = {start[0:2]: 0}  # {(row, col): wall breaks}
    while queue:
        r, c, b = queue.popleft()
        if (r, c) == end:
            return b
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '#':
                    if (nr, nc) not in visited or visited[nr, nc] == b + 1:
                        visited[nr, nc] = b + 1
                        queue.append((nr, nc, b + 1))
                else:
                    if (nr, nc) not in visited or visited[nr, nc] == b:
                        visited[nr, nc] = b
                        queue.appendleft((nr, nc, b))  # appendleft to prioritize breaking the wall
    return -1

