from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    get_results = []

    for op in operations:
        if op[0] == "put":
            if len(cache) == capacity:
                cache.popitem(last=False)  # Remove the least recently used item
            cache[op[1]] = op[2]
            cache.move_to_end(op[1])  # Mark the accessed item as the most recently used
        elif op[0] == "get":
            if op[1] in cache:
                get_results.append(cache[op[1]])
                cache.move_to_end(op[1])  # Mark the accessed item as the most recently used
            else:
                get_results.append(None)

    return get_results, list(cache.keys())
