            elif len(cache) == capacity:
                del cache[keys[0]]
                keys.pop(0)
            cache[key] = value
            keys.append(key)
            results.append(None)

        elif op == "get":
            if key in cache:
                results.append(cache[key])
                keys.remove(key)
                keys.append(key)
            else:
                results.append(None)

    return results, keys
